 16→// Ensure KiroAgent implements HookSupport
 17→var _ agent.HookSupport = (*KiroAgent)(nil)
 18→
 19→// HooksFileName is the config file for Kiro hooks.
 20→const HooksFileName = "entire.json"
 21→
 22→// hooksDir is the directory within .kiro where agent hook configs live.
 23→const hooksDir = "agents"
 24→
 25→// localDevCmdPrefix is the command prefix used for local development builds.
 26→const localDevCmdPrefix = "go run ${KIRO_PROJECT_DIR}/cmd/entire/main.go "
 27→
 28→// entireHookPrefixes identify Entire hooks in the config file.
 29→var entireHookPrefixes = []string{
 30→	"entire ",
 31→	localDevCmdPrefix,
 32→}
 33→
 34→// InstallHooks installs Entire hooks in .kiro/agents/entire.json.
 35→// Since Entire owns this file entirely, we write it from scratch each time.
 36→// Returns the number of hooks installed.
 37→func (k *KiroAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 38→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 39→	if err != nil {
 40→		worktreeRoot = "."
 41→	}
 42→
 43→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
 44→
 45→	// If hooks are already installed and not forcing, check if they're current
 46→	if !force {
 47→		if existing, readErr := os.ReadFile(hooksPath); readErr == nil { //nolint:gosec // path constructed from repo root
 48→			var file kiroAgentFile
 49→			if json.Unmarshal(existing, &file) == nil && allHooksPresent(file.Hooks, localDev) {
 50→				return 0, nil
 51→			}
 52→		}
 53→	}
 54→
 55→	var cmdPrefix string
 56→	if localDev {
 57→		cmdPrefix = localDevCmdPrefix + "hooks kiro "
 58→	} else {
 59→		cmdPrefix = "entire hooks kiro "
 60→	}
 61→
 62→	file := kiroAgentFile{
 63→		Name: "entire",
 64→		// Include all default Kiro tools so the agent profile doesn't restrict them.
 65→		Tools: []string{
 66→			"read", "write", "shell", "grep", "glob",
 67→			"aws", "report", "introspect", "knowledge",
 68→			"thinking", "todo", "delegate",
 69→		},
 70→		Hooks: kiroHooks{
 71→			AgentSpawn:       []kiroHookEntry{{Command: cmdPrefix + HookNameAgentSpawn}},
 72→			UserPromptSubmit: []kiroHookEntry{{Command: cmdPrefix + HookNameUserPromptSubmit}},
 73→			PreToolUse:       []kiroHookEntry{{Command: cmdPrefix + HookNamePreToolUse}},
 74→			PostToolUse:      []kiroHookEntry{{Command: cmdPrefix + HookNamePostToolUse}},
 75→			Stop:             []kiroHookEntry{{Command: cmdPrefix + HookNameStop}},
 76→		},
 77→	}
 78→
 79→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
 80→		return 0, fmt.Errorf("failed to create .kiro/agents directory: %w", err)
 81→	}
 82→
 83→	output, err := jsonutil.MarshalIndentWithNewline(file, "", "  ")
 84→	if err != nil {
 85→		return 0, fmt.Errorf("failed to marshal hooks config: %w", err)
 86→	}
 87→
 88→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
 89→		return 0, fmt.Errorf("failed to write hooks config: %w", err)
 90→	}
 91→
 92→	return len(k.HookNames()), nil
 93→}
