 95→// UninstallHooks removes the Entire hooks config file.
 96→func (k *KiroAgent) UninstallHooks(ctx context.Context) error {
 97→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 98→	if err != nil {
 99→		worktreeRoot = "."
100→	}
101→
102→	hooksPath := filepath.Join(worktreeRoot, ".kiro", hooksDir, HooksFileName)
103→	if err := os.Remove(hooksPath); err != nil && !os.IsNotExist(err) {
104→		return fmt.Errorf("failed to remove hooks config: %w", err)
105→	}
106→	return nil
107→}
