143→func allHooksPresent(hooks kiroHooks, localDev bool) bool {
144→	var cmdPrefix string
145→	if localDev {
146→		cmdPrefix = localDevCmdPrefix + "hooks kiro "
147→	} else {
148→		cmdPrefix = "entire hooks kiro "
149→	}
150→
151→	return hookCommandExists(hooks.AgentSpawn, cmdPrefix+HookNameAgentSpawn) &&
152→		hookCommandExists(hooks.UserPromptSubmit, cmdPrefix+HookNameUserPromptSubmit) &&
153→		hookCommandExists(hooks.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
154→		hookCommandExists(hooks.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
155→		hookCommandExists(hooks.Stop, cmdPrefix+HookNameStop)
156→}
157→
158→func hookCommandExists(entries []kiroHookEntry, command string) bool {
159→	for _, entry := range entries {
160→		if entry.Command == command {
161→			return true
162→		}
163→	}
164→	return false
165→}
166→
167→func isEntireHook(command string) bool {
168→	for _, prefix := range entireHookPrefixes {
169→		if strings.HasPrefix(command, prefix) {
170→			return true
171→		}
172→	}
173→	return false
174→}
175→
176→func hasEntireHook(entries []kiroHookEntry) bool {
177→	for _, entry := range entries {
178→		if isEntireHook(entry.Command) {
179→			return true
180→		}
181→	}
182→	return false
183→}
